       cout<<"p+"<<i<<":"<<p+i<<endl;
       cout<<"p["<<i<<"]:"<<p[i]<<endl;
   }
    
    delete[] p;
        cout<<"-------------------After delete------------------------"<<endl;
    for(int i=0;i<20;i++)
   {
       cout<<"p+"<<i<<":"<<p+i<<endl;
       cout<<"p["<<i<<"]:"<<p[i]<<endl;
   }
   return 0;
}


